'use strict';
(()=>{
 const el=(s)=>document.querySelector(s);
 const saved=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
 const remember=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
 const teach={list:[],index:0,panel:'board',tool:'pointer',color:'#d24b40',width:3,zoom:100,reveal:0,hidden:false,focused:false,sidebar:false,redo:{question:[],board:[]},data:null};
 const storage='sz-quadratic-classroom-v1';
 let timerEnd=0,timerRemaining=180,timerHandle,autosave,canvasViews={},previousFocus=null;
 const root=document.createElement('section');root.id='classroom';root.hidden=true;root.setAttribute('aria-label','二次函数授课模式');
 root.innerHTML=`
 <header class="class-header"><div class="class-brand"><span class="class-dot"></span><b>深圳数学</b><span>授课模式</span></div>
 <div class="class-head-actions"><button id="classCatalog" aria-pressed="false">☷ 题目目录</button><button id="classFocus" aria-pressed="false">专注题目</button><button id="classFullscreen">⛶ 全屏</button><button id="exitClass">返回题库</button></div></header>
 <div class="class-body"><aside id="classSidebar" class="class-sidebar" hidden><div class="class-side-top"><h2>本次授课</h2><button id="closeCatalog" aria-label="收起目录">×</button></div><p id="classFilterNote"></p><label class="sr-only" for="classSearch">在本次题目中搜索</label><input id="classSearch" type="search" placeholder="搜索标题、年份、考点"><div id="classQuestionList"></div></aside>
 <main class="class-main"><div class="class-question-heading"><div><p id="classMeta"></p><h1 id="classTitle"></h1></div><div class="class-zoom"><button id="classZoomOut" aria-label="缩小题目">−</button><output id="classZoomLabel">100%</output><button id="classZoomIn" aria-label="放大题目">＋</button><button id="classZoomFit">适宽</button></div></div>
 <div class="class-tools" aria-label="板书工具"><div class="tool-group" role="group" aria-label="选择工具"><button data-tool="pointer" title="浏览 / V" aria-pressed="true">↖ 浏览</button><button data-tool="pen" title="画笔 / P" aria-pressed="false">✎ 画笔</button><button data-tool="highlight" title="荧光笔 / H" aria-pressed="false">▰ 荧光</button><button data-tool="line" title="直线" aria-pressed="false">╱ 直线</button><button data-tool="arrow" title="箭头" aria-pressed="false">↗ 箭头</button><button data-tool="rect" title="方框" aria-pressed="false">□ 方框</button><button data-tool="eraser" title="擦除整条笔迹 / E" aria-pressed="false">▱ 橡皮</button></div>
 <div class="tool-colors" role="group" aria-label="笔迹颜色"><button data-color="#d24b40" style="--swatch:#d24b40" aria-label="红色" aria-pressed="true"></button><button data-color="#2863a6" style="--swatch:#2863a6" aria-label="蓝色" aria-pressed="false"></button><button data-color="#1b6654" style="--swatch:#1b6654" aria-label="绿色" aria-pressed="false"></button><button data-color="#253d36" style="--swatch:#253d36" aria-label="黑色" aria-pressed="false"></button></div>
 <label class="pen-width">粗细 <select id="classPenWidth" aria-label="画笔粗细"><option value="3">细</option><option value="5">中</option><option value="8">粗</option></select></label><span class="tools-hint" id="toolHint">选择画笔，可在原题或白板上圈画</span></div>
 <div class="class-panels"><section class="question-panel" aria-label="当前题目"><div class="pane-label"><span>题目 <small id="questionPartInfo"></small></span><div><button id="questionUndo" title="撤销题目上的笔迹">↶ 撤销</button><button id="questionRedo" title="重做题目上的笔迹">↷ 重做</button><button id="questionClear">清除圈画</button><button id="hideQuestion">暂时遮题</button></div></div>
 <div class="question-scroll" id="questionScroll"><div class="question-paper" id="questionPaper"><div id="classQuestionContent"></div><canvas id="questionCanvas" aria-label="题目批注画布"></canvas></div><div class="question-curtain" id="questionCurtain" hidden><span>先想一想</span><p>回忆题意，试着说出解题思路。</p><button class="primary-btn" id="restoreQuestion">继续看题目</button></div></div></section>
 <aside class="teaching-panel"><div class="teaching-tabs" role="tablist" aria-label="讲解区域"><button role="tab" id="boardTab" aria-controls="boardPanel" data-panel="board" aria-selected="true">板书</button><button role="tab" id="solutionTab" aria-controls="solutionPanel" data-panel="solution" aria-selected="false">分段解析</button><button role="tab" id="graphTab" aria-controls="graphPanel" data-panel="graph" aria-selected="false">函数图</button></div>
 <section id="boardPanel" role="tabpanel" aria-labelledby="boardTab" class="teach-panel-content"><div class="board-bar"><label><input type="checkbox" id="boardGrid" checked> 方格</label><span><button id="boardUndo">↶ 撤销</button><button id="boardRedo">↷ 重做</button><button id="boardClear">清空笔迹</button></span></div><div class="board-stage grid" id="boardStage"><canvas id="boardCanvas" aria-label="自由板书画布"></canvas><span class="board-placeholder" id="boardPlaceholder">在这里画辅助线、圈重点<br><small>也可以在下方用键盘输入板书</small></span></div>
 <div class="keyboard-board"><div class="keyboard-heading"><b>键盘板书</b><span id="boardSaved" role="status">自动保存在当前浏览器</span></div><div class="formula-chips"><button data-insert="y = a(x − h)² + k">顶点式</button><button data-insert="x = −b / (2a)">对称轴</button><button data-insert="y = ax² + bx + c">一般式</button><button data-insert="S = ½ × 底 × 高">面积</button><button data-insert="∵　\n∴　">∵ ∴</button><button data-insert="²">x²</button><button data-insert="√">√</button></div><label class="sr-only" for="keyboardNotes">本题键盘板书</label><textarea id="keyboardNotes" spellcheck="false" placeholder="直接打字，学生共享屏幕就能看到。\n例如：设点 P 的横坐标为 t\n已知 → 列式 → 变形 → 结论"></textarea><div class="board-bottom"><label>字号 <select id="boardFont"><option>22</option><option selected>26</option><option>32</option><option>40</option></select></label><button id="fillOutline">插入本题讲解提纲</button></div></div></section>
 <section id="solutionPanel" role="tabpanel" aria-labelledby="solutionTab" class="teach-panel-content" hidden><div class="solution-controls"><p id="revealCounter">解析尚未展示</p><div><button id="hideSteps">收起全部</button><button id="nextStep" class="primary-btn">展示下一段</button></div></div><div class="solution-scroll" id="classSolutionContent"><div class="solution-placeholder"><span>先思考，再看解析</span><p>点击“展示下一段”，逐段讲解。</p></div></div></section>
 <section id="graphPanel" role="tabpanel" aria-labelledby="graphTab" class="teach-panel-content" hidden><div class="graph-top"><p>二次函数演示 <small>通用工具，可按本题参数调整</small></p><div id="liveEquation" class="live-equation"></div></div><svg id="classGraph" viewBox="0 0 500 400" role="img" aria-label="可调参数的二次函数图象"></svg><div class="graph-controls"><label>a <input id="graphA" type="range" min="-4" max="4" value="1" step="0.25"><output id="valueA">1</output></label><label>h <input id="graphH" type="range" min="-6" max="6" value="0" step="0.5"><output id="valueH">0</output></label><label>k <input id="graphK" type="range" min="-6" max="8" value="0" step="0.5"><output id="valueK">0</output></label><div class="graph-options"><label><input id="graphOriginal" type="checkbox" checked> 对比 y = ax²</label><button id="graphReset">重置</button><button id="graphTranslation">演示本题平移</button></div><p id="graphFacts"></p></div></section></aside></div>
 <footer class="class-footer"><div class="class-paging"><button id="prevQuestion">← 上一题</button><span id="classPosition"></span><button id="nextQuestion">下一题 →</button></div><div class="class-timer"><label class="sr-only" for="timerLength">思考时长</label><select id="timerLength"><option value="60">1分钟</option><option value="180" selected>3分钟</option><option value="300">5分钟</option><option value="600">10分钟</option></select><button id="timerToggle">开始计时</button><output id="timerDisplay" aria-live="off">03:00</output><button id="timerReset" title="重置计时">↺</button></div><span class="shortcut-hint">← → 切题 · P 画笔 · V 浏览 · Esc 返回</span></footer>
 </main></div><div class="class-toast" id="classToast" role="status"></div>`;
 document.body.append(root);
 const ce=s=>root.querySelector(s);
 let messageTimeout;function message(t){ce('#classToast').textContent=t;ce('#classToast').classList.add('show');clearTimeout(messageTimeout);messageTimeout=setTimeout(()=>ce('#classToast').classList.remove('show'),2600)}
 function current(){return teach.list[teach.index]}
 function loadData(){const q=current();teach.data=saved(storage+':'+q.id,{question:[],board:[],notes:'',font:26,grid:true});for(const t of ['question','board'])if(!Array.isArray(teach.data[t]))teach.data[t]=[];teach.redo={question:[],board:[]};}
 function save(){if(!teach.data||!current())return;const ok=remember(storage+':'+current().id,teach.data);ce('#boardSaved').textContent=ok?'已保存在当前浏览器':'浏览器存储空间不足，请复制板书文字留存';}
 function catalog(){let value=ce('#classSearch').value.trim();ce('#classQuestionList').innerHTML=teach.list.map((q,i)=>({q,i})).filter(({q})=>!value||`${q.title} ${q.category} ${q.year}`.includes(value)).map(({q,i})=>`<button data-class-index="${i}" class="catalog-question ${i===teach.index?'selected':''}" ${i===teach.index?'aria-current="true"':''}><span>${String(i+1).padStart(2,'0')}</span><div><b>${escaped(q.title)}</b><small>${q.year} · ${escaped(q.type)} · ${escaped(q.category)}</small></div></button>`).join('')||'<p class="no-catalog-results">没有匹配的题目</p>';ce('#classFilterNote').textContent=`${teach.list.length} 道题，沿用题库当前的筛选和排序`;}
 function setTool(t){teach.tool=t;root.dataset.tool=t;root.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tool===t)));ce('#toolHint').textContent=t==='pointer'?'浏览模式：可以滚动题目和操作控件':t==='eraser'?'点击或划过笔迹，擦除整条笔迹':'可在题目或白板上直接圈画；V 返回浏览';}
 function open(id){if(!questions.length)return toast('题目还在加载，请稍候');previousFocus=document.activeElement;teach.list=filteredQuestions();if(!teach.list.length)teach.list=[...questions];let i=teach.list.findIndex(q=>q.id===id);if(i<0){i=teach.list.findIndex(q=>q.id===saved(storage+':last',''));}teach.index=Math.max(0,i);root.hidden=false;document.body.classList.add('class-open');renderQuestion();ce('#exitClass').focus();}
 function close(){save();pauseTimer();root.hidden=true;document.body.classList.remove('class-open');if(document.fullscreenElement===root&&document.exitFullscreen)document.exitFullscreen().catch(()=>{});previousFocus?.focus();}
 function switchQuestion(delta){const index=teach.index+delta;if(index<0||index>=teach.list.length)return;save();teach.index=index;renderQuestion();}
 function renderQuestion(){loadData();const q=current();teach.reveal=0;teach.hidden=false;ce('#questionCurtain').hidden=true;ce('#hideQuestion').textContent='暂时遮题';ce('#classMeta').textContent=`${q.year}年 · ${q.type} · ${q.category} · 原书 p.${q.page}`;ce('#classTitle').textContent=q.title;ce('#questionPartInfo').textContent=q.note?'已标注原稿问题':'';ce('#classPosition').textContent=`${teach.index+1} / ${teach.list.length}`;ce('#prevQuestion').disabled=teach.index===0;ce('#nextQuestion').disabled=teach.index===teach.list.length-1;
 ce('#classQuestionContent').innerHTML=correctedQuestion(q)||`${q.note?`<p class="class-correction">${escaped(q.note)}</p>`:''}${q.question.map((im,i)=>`<figure><img draggable="false" src="${im.src}" width="${im.width}" height="${im.height}" alt="${escaped(q.title)}，原题第${i+1}部分"><figcaption>原题第 ${i+1} / ${q.question.length} 部分 · 原书 p.${im.pdfPage-2} <button data-class-zoom="${im.src}">单独放大 ↗</button></figcaption></figure>`).join('')}`;
 ce('#keyboardNotes').value=teach.data.notes||'';ce('#boardFont').value=String(teach.data.font||26);ce('#keyboardNotes').style.fontSize=(teach.data.font||26)+'px';ce('#boardGrid').checked=teach.data.grid!==false;ce('#boardStage').classList.toggle('grid',teach.data.grid!==false);ce('#questionScroll').scrollTop=0;ce('#questionScroll').scrollLeft=0;teach.zoom=100;setZoom(100);setTool('pointer');catalog();renderSteps();remember(storage+':last',q.id);resetTimer();requestAnimationFrame(resizeAll);
 ce('#classQuestionContent').querySelectorAll('img').forEach(im=>im.addEventListener('load',resizeAll,{once:true}));ce('#graphTranslation').hidden=q.id!=='s15q03';}
 function setZoom(z){teach.zoom=Math.max(60,Math.min(200,z));ce('#questionPaper').style.width=teach.zoom+'%';ce('#classZoomLabel').textContent=teach.zoom+'%';requestAnimationFrame(resizeAll);}
 function panel(name){teach.panel=name;root.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.panel===name)));for(const k of ['board','solution','graph'])ce('#'+k+'Panel').hidden=k!==name;if(name==='graph')drawGraph();requestAnimationFrame(resizeAll);}
 function stepList(){const q=current(),fixed=correctedLessonSteps(q);if(fixed)return fixed;return q.solution.filter(im=>im.height>=55).map((im,i)=>({title:`原解析 · 第 ${i+1} 部分`,html:`<img src="${im.src}" alt="${escaped(q.title)}原解析第${i+1}部分" width="${im.width}" height="${im.height}"><button class="solution-zoom" data-class-zoom="${im.src}">放大这一段 ↗</button>`}));}
 function renderSteps(){const steps=stepList();ce('#revealCounter').textContent=`已展示 ${teach.reveal} / ${steps.length} 段`;ce('#nextStep').disabled=teach.reveal>=steps.length;ce('#nextStep').textContent=teach.reveal>=steps.length?'已全部展示':'展示下一段';ce('#classSolutionContent').innerHTML=teach.reveal?steps.slice(0,teach.reveal).map((s,i)=>`<article class="lecture-step"><h3><span>${i+1}</span>${s.title}</h3>${s.html}</article>`).join(''):'<div class="solution-placeholder"><span>先思考，再看解析</span><p>点击“展示下一段”，逐段讲解。</p></div>';}
 function nextStep(){const steps=stepList();if(teach.reveal<steps.length){teach.reveal++;renderSteps();ce('#classSolutionContent').lastElementChild?.scrollIntoView({block:'nearest',behavior:'smooth'});}}
 function resizeAll(){if(root.hidden||!teach.data)return;for(const kind of ['question','board']){const canvas=ce('#'+kind+'Canvas'),parent=canvas.parentElement;if(!parent.clientWidth||!parent.clientHeight)continue;const w=parent.clientWidth,h=parent.clientHeight;const dpr=Math.min(window.devicePixelRatio||1,2,Math.sqrt(16000000/(w*h)));canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvasViews[kind]={w,h,dpr};paint(kind);}ce('#boardPlaceholder').hidden=!!teach.data.board.length;}
 function stroke(ctx,s,w,h){const pts=s.points;if(!pts?.length)return;ctx.save();ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineWidth=s.tool==='highlight'?20:s.width;ctx.lineCap='round';ctx.lineJoin='round';ctx.globalAlpha=s.tool==='highlight'?0.28:1;const first=pts[0],last=pts[pts.length-1],a={x:first.x*w,y:first.y*h},b={x:last.x*w,y:last.y*h};ctx.beginPath();if(s.tool==='rect'){ctx.rect(a.x,a.y,b.x-a.x,b.y-a.y);}else if(s.tool==='arrow'){ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);const angle=Math.atan2(b.y-a.y,b.x-a.x),size=14;ctx.moveTo(b.x-size*Math.cos(angle-.5),b.y-size*Math.sin(angle-.5));ctx.lineTo(b.x,b.y);ctx.lineTo(b.x-size*Math.cos(angle+.5),b.y-size*Math.sin(angle+.5));}else if(s.tool==='line'){ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);}else{ctx.moveTo(a.x,a.y);for(const p of pts)ctx.lineTo(p.x*w,p.y*h);if(pts.length===1){ctx.lineTo(a.x+.1,a.y+.1)}}ctx.stroke();ctx.restore();}
 function paint(kind,draft){const canvas=ce('#'+kind+'Canvas'),v=canvasViews[kind];if(!v)return;const ctx=canvas.getContext('2d');ctx.setTransform(v.dpr,0,0,v.dpr,0,0);ctx.clearRect(0,0,v.w,v.h);for(const s of teach.data[kind])stroke(ctx,s,v.w,v.h);if(draft)stroke(ctx,draft,v.w,v.h);}
 function point(e,canvas){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};}
 function segmentDist(p,a,b,w,h){let px=p.x*w,py=p.y*h,ax=a.x*w,ay=a.y*h,bx=b.x*w,by=b.y*h;const dx=bx-ax,dy=by-ay;const t=Math.max(0,Math.min(1,((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(px-ax-t*dx,py-ay-t*dy);}
 function erase(kind,p){const v=canvasViews[kind];const arr=teach.data[kind];for(let i=arr.length-1;i>=0;i--){const s=arr[i];let pts=s.points;if(s.tool==='rect'&&pts.length>1){let a=pts[0],b=pts.at(-1);pts=[a,{x:b.x,y:a.y},b,{x:a.x,y:b.y},a];}const hit=pts.length===1?segmentDist(p,pts[0],pts[0],v.w,v.h)<16:pts.some((pt,j)=>j&&segmentDist(p,pts[j-1],pt,v.w,v.h)<16);if(hit){teach.redo[kind]=[];arr.splice(i,1);paint(kind);return;}}}
 for(const kind of ['question','board']){const canvas=ce('#'+kind+'Canvas');let drawing=null,erasing=false;canvas.addEventListener('pointerdown',e=>{if(teach.tool==='pointer'||e.button>0)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);if(teach.tool==='eraser'){erasing=true;erase(kind,point(e,canvas));return;}drawing={tool:teach.tool,color:teach.color,width:teach.width,points:[point(e,canvas)]};paint(kind,drawing);});canvas.addEventListener('pointermove',e=>{if(erasing){erase(kind,point(e,canvas));return;}if(!drawing)return;const p=point(e,canvas);if(['line','arrow','rect'].includes(drawing.tool))drawing.points=[drawing.points[0],p];else drawing.points.push(p);paint(kind,drawing);});const finish=()=>{if(drawing){teach.data[kind].push(drawing);teach.redo[kind]=[];drawing=null;paint(kind);ce('#boardPlaceholder').hidden=!!teach.data.board.length;save();}if(erasing){erasing=false;save();}};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);}
 function undo(kind){const s=teach.data[kind].pop();if(s){teach.redo[kind].push(s);paint(kind);save();ce('#boardPlaceholder').hidden=!!teach.data.board.length;}}
 function redo(kind){const s=teach.redo[kind].pop();if(s){teach.data[kind].push(s);paint(kind);save();ce('#boardPlaceholder').hidden=!!teach.data.board.length;}}
 function clear(kind){if(!teach.data[kind].length)return;teach.redo[kind]=[...teach.data[kind]].reverse();teach.data[kind]=[];paint(kind);save();ce('#boardPlaceholder').hidden=!!teach.data.board.length;message('已清除笔迹，可点“重做”逐条恢复');}
 const outlines={
 '图象与性质':'① 看开口：确定 a 的正负\n② 找顶点与对称轴\n③ 代入特殊点，核对各项结论\n④ 对照图象检查',
 '最值与参数':'① 确定自变量范围\n② 代入条件，求参数\n③ 配方，写出顶点式\n④ 检查顶点是否在范围内\n⑤ 比较端点，写结论',
 '平移与交点':'① 找原顶点\n② 按“左加右减，上加下减”写新函数\n③ 令两个函数的 y 相等\n④ 求 x 后代回求 y\n⑤ 按对称轴两侧讨论',
 '利润应用':'① 设自变量，写取值范围\n② 每件利润 = 售价 − 成本\n③ 总利润 = 每件利润 × 销量\n④ 配方并检查顶点\n⑤ 回答售价、数量与最大利润',
 '实际建模':'① 选原点与坐标轴\n② 把已知长度转成点的坐标\n③ 选合适的函数表达式\n④ 代入条件求系数\n⑤ 检查结果是否符合实际',
 '动点与几何':'① 设动点坐标或运动时间\n② 标出位置变化的分界点\n③ 分类讨论几何关系\n④ 列面积或距离表达式\n⑤ 在各自范围内比较并检验'};
 function fillOutline(){const q=current();const insert=`${q.title}\n本题重点：${q.focus}\n\n${outlines[q.category]||'已知：\n所求：\n思路：\n列式：\n结论：'}`;ce('#keyboardNotes').value+=(ce('#keyboardNotes').value?'\n\n':'')+insert;ce('#keyboardNotes').dispatchEvent(new Event('input'));message('已插入解题提纲，可直接编辑补充');}
 function pauseTimer(){if(timerHandle){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));clearInterval(timerHandle);timerHandle=null;}ce('#timerToggle').textContent='继续计时';}
 function displayTimer(){ce('#timerDisplay').value=String(Math.floor(timerRemaining/60)).padStart(2,'0')+':'+String(timerRemaining%60).padStart(2,'0');ce('#timerDisplay').classList.toggle('timer-over',timerRemaining===0);}
 function resetTimer(){clearInterval(timerHandle);timerHandle=null;timerRemaining=Number(ce('#timerLength').value);displayTimer();ce('#timerToggle').textContent='开始计时';}
 function toggleTimer(){if(timerHandle){pauseTimer();return;}if(timerRemaining<=0)resetTimer();timerEnd=Date.now()+timerRemaining*1000;ce('#timerToggle').textContent='暂停';timerHandle=setInterval(()=>{timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));displayTimer();if(!timerRemaining){clearInterval(timerHandle);timerHandle=null;ce('#timerToggle').textContent='重新开始';message('思考时间到，可以开始讨论了');}},250);}
 function drawGraph(){const a=+ce('#graphA').value,h=+ce('#graphH').value,k=+ce('#graphK').value;ce('#valueA').value=a;ce('#valueH').value=h;ce('#valueK').value=k;const x0=250,y0=270,s=25;let svg='<defs><clipPath id="graphClip"><rect x="26" y="20" width="450" height="350"/></clipPath></defs><rect x="26" y="20" width="450" height="350" fill="#fcfdfb"/>';for(let i=-8;i<=8;i++){svg+=`<path d="M${x0+i*s} 20V370" stroke="#e5eae2"/><text x="${x0+i*s}" y="${y0+17}" text-anchor="middle" font-size="10" fill="#6e8279">${i||''}</text>`;}for(let i=-3;i<=9;i++){svg+=`<path d="M26 ${y0-i*s}H476" stroke="#e5eae2"/><text x="${x0-7}" y="${y0-i*s+4}" text-anchor="end" font-size="10" fill="#6e8279">${i||''}</text>`;}svg+=`<path d="M26 ${y0}H480 M${x0} 373V15" stroke="#84988e" stroke-width="1.5"/><text x="482" y="${y0-7}" font-size="13">x</text><text x="${x0+8}" y="18" font-size="13">y</text><text x="${x0+6}" y="${y0+16}" font-size="12">O</text>`;
 function curve(hh,kk,color,dash){let d='';for(let x=-9;x<=9;x+=.04){const xx=x0+x*s,yy=y0-(a*(x-hh)*(x-hh)+kk)*s;d+=(d?'L':'M')+xx.toFixed(1)+' '+yy.toFixed(1);}return`<path d="${d}" fill="none" stroke="${color}" stroke-width="2.8" ${dash?'stroke-dasharray="5 5"':''} clip-path="url(#graphClip)"/>`;}
 if(ce('#graphOriginal').checked)svg+=curve(0,0,'#b8c4b8',true);svg+=curve(h,k,'#1b6654',false);if(a!==0)svg+=`<path d="M${x0+h*s} 20V370" stroke="#b9754b" stroke-dasharray="4 4" clip-path="url(#graphClip)"/><circle cx="${x0+h*s}" cy="${y0-k*s}" r="5" fill="#d24b40"/><text x="${Math.min(410,x0+h*s+10)}" y="${y0-k*s-10}" font-size="15" fill="#1b6654">(${h}, ${k})</text>`;ce('#classGraph').innerHTML=svg;ce('#liveEquation').textContent=`y = ${a}(${h<0?'x + '+Math.abs(h):'x − '+h})² ${k<0?'− '+Math.abs(k):'+ '+k}`;ce('#graphFacts').textContent=a===0?'a = 0，此时退化为常函数，不是二次函数。':`${a>0?'开口向上':'开口向下'} · 顶点 (${h}, ${k}) · 对称轴 x = ${h} · ${a>0?'最小值':'最大值'} ${k}`;
 }
 root.addEventListener('click',e=>{const t=e.target.closest('[data-tool]');if(t)setTool(t.dataset.tool);const c=e.target.closest('[data-color]');if(c){teach.color=c.dataset.color;root.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b===c)));}const p=e.target.closest('[data-panel]');if(p)panel(p.dataset.panel);const q=e.target.closest('[data-class-index]');if(q){save();teach.index=+q.dataset.classIndex;renderQuestion();}const insert=e.target.closest('[data-insert]');if(insert){const area=ce('#keyboardNotes');const start=area.selectionStart,end=area.selectionEnd;area.setRangeText(insert.dataset.insert.replace(/\\n/g,'\n'),start,end,'end');area.dispatchEvent(new Event('input'));area.focus();}const zoom=e.target.closest('[data-class-zoom]');if(zoom){el('#zoomImage').src=zoom.dataset.classZoom;el('#zoomImage').alt=current().title;el('#imageCaption').textContent=current().title+' · 原书 p.'+current().page;el('#imageDialog').showModal();}});
 document.addEventListener('click',e=>{const t=e.target.closest('[data-teach]');if(t)open(t.dataset.teach);});
 el('#startClass').addEventListener('click',()=>open());
 ce('#exitClass').onclick=close;ce('#prevQuestion').onclick=()=>switchQuestion(-1);ce('#nextQuestion').onclick=()=>switchQuestion(1);ce('#classZoomOut').onclick=()=>setZoom(teach.zoom-20);ce('#classZoomIn').onclick=()=>setZoom(teach.zoom+20);ce('#classZoomFit').onclick=()=>setZoom(100);ce('#classPenWidth').onchange=e=>teach.width=+e.target.value;
 ce('#classCatalog').onclick=()=>{teach.sidebar=!teach.sidebar;ce('#classSidebar').hidden=!teach.sidebar;ce('#classCatalog').setAttribute('aria-pressed',String(teach.sidebar));requestAnimationFrame(resizeAll)};ce('#closeCatalog').onclick=()=>ce('#classCatalog').click();ce('#classSearch').oninput=catalog;
 ce('#classFocus').onclick=()=>{teach.focused=!teach.focused;root.classList.toggle('question-focused',teach.focused);ce('#classFocus').textContent=teach.focused?'题目 + 讲解':'专注题目';ce('#classFocus').setAttribute('aria-pressed',String(teach.focused));requestAnimationFrame(resizeAll)};
 ce('#classFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(root.requestFullscreen)await root.requestFullscreen();else message('可用浏览器全屏功能放大授课区')}catch{message('当前环境不支持全屏，可使用浏览器全屏功能')}};
 document.addEventListener('fullscreenchange',()=>{ce('#classFullscreen').textContent=document.fullscreenElement?'退出全屏':'⛶ 全屏';requestAnimationFrame(resizeAll)});
 ce('#hideQuestion').onclick=()=>{teach.hidden=!teach.hidden;ce('#questionCurtain').hidden=!teach.hidden;ce('#hideQuestion').textContent=teach.hidden?'恢复题目':'暂时遮题';};ce('#restoreQuestion').onclick=()=>ce('#hideQuestion').click();
 ce('#nextStep').onclick=nextStep;ce('#hideSteps').onclick=()=>{teach.reveal=0;renderSteps()};
 for(const kind of ['question','board']){ce('#'+kind+'Undo').onclick=()=>undo(kind);ce('#'+kind+'Redo').onclick=()=>redo(kind);ce('#'+kind+'Clear').onclick=()=>clear(kind)}
 ce('#boardGrid').onchange=e=>{teach.data.grid=e.target.checked;ce('#boardStage').classList.toggle('grid',e.target.checked);save()};ce('#keyboardNotes').oninput=e=>{teach.data.notes=e.target.value;clearTimeout(autosave);autosave=setTimeout(save,250)};ce('#boardFont').onchange=e=>{teach.data.font=+e.target.value;ce('#keyboardNotes').style.fontSize=e.target.value+'px';save()};ce('#fillOutline').onclick=fillOutline;
 ce('#timerToggle').onclick=toggleTimer;ce('#timerReset').onclick=resetTimer;ce('#timerLength').onchange=resetTimer;
 for(const id of ['graphA','graphH','graphK','graphOriginal'])ce('#'+id).oninput=drawGraph;ce('#graphReset').onclick=()=>{ce('#graphA').value=1;ce('#graphH').value=ce('#graphK').value=0;drawGraph()};ce('#graphTranslation').onclick=()=>{ce('#graphA').value=2;ce('#graphH').value=3;ce('#graphK').value=6;drawGraph()};
 document.addEventListener('keydown',e=>{if(root.hidden||el('#imageDialog').open)return;if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='Escape'){e.preventDefault();close()}else if(e.key==='ArrowRight'){e.preventDefault();switchQuestion(1)}else if(e.key==='ArrowLeft'){e.preventDefault();switchQuestion(-1)}else if(e.key.toLowerCase()==='p')setTool('pen');else if(e.key.toLowerCase()==='v')setTool('pointer');else if(e.key.toLowerCase()==='h')setTool('highlight');else if(e.key.toLowerCase()==='e')setTool('eraser');else if(e.key===' '&&teach.panel==='solution'){e.preventDefault();nextStep()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo(teach.panel==='board'?'board':'question'):undo(teach.panel==='board'?'board':'question')}});
 new ResizeObserver(()=>{if(!root.hidden)requestAnimationFrame(resizeAll)}).observe(ce('#questionPaper'));new ResizeObserver(()=>{if(!root.hidden)requestAnimationFrame(resizeAll)}).observe(ce('#boardStage'));window.addEventListener('beforeunload',save);
 document.addEventListener('questions-ready',()=>{const params=new URLSearchParams(location.search);if(params.has('class'))open(params.get('q')||undefined)});
})();
